import{_ as r,a0 as d,w as i,s,ao as l,I as a,a1 as n,A as p,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/15 - The history of Android","title":"安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變","tag":"The history of Android","desc":""},"relativePath":"The history of Android/15 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/15 - The history of Android.md"};function g(u,o,h,T,f,A){const e=d("Link");return i(),s("div",null,[o[14]||(o[14]=l('<h1 id="安卓編年史-15-android-2-3-gingerbread——第一次-ui-大變" tabindex="-1">安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變 <a class="header-anchor" href="#安卓編年史-15-android-2-3-gingerbread——第一次-ui-大變" aria-label="Permalink to “安卓編年史（15）：Android 2.3 Gingerbread——第一次 UI 大變”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/3kb-high-over-check.png" alt="薑餅的新鍵盤，文本選擇，邊界回彈效果以及新複選框。"></p><p><em>薑餅的新鍵盤，文本選擇，邊界回彈效果以及新複選框。 [Ron Amadeo 供圖]</em></p><p>安卓 2.3 最重要的新增功能就是系統全局文本選擇界面，你可以在左側截圖的谷歌搜索欄看到它。長按一個詞能使其變為橙色高亮，並且出現可拖拽的小標籤，長按高亮部分會彈出剪切、複製和粘貼選項。之前的方法使用的是依賴於十字方向鍵的控制，但現在有了觸摸文本選擇，Nexus S 不再需要額外的硬件控件。</p><p>左側截圖右半邊展示的是新的複選框設計和邊界回彈效果。凍酸奶（2.2）的複選框像個燈泡——選中時顯示一個綠色的勾，未選中的時候顯示灰色的勾。薑餅在選項關閉的時候顯示一個空的選框——這顯得更有意義。薑餅是第一個擁有滾動到底發光效果的版本。當到達列表底部的時候會有一道橙色的光暈，你越往上拉光暈越明顯。列表上拉滾動反彈也許最直觀，但那是蘋果的專利。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/dialdialog.png" alt="新撥號界面和對話框設計。"><em>新撥號界面和對話框設計。 [Ron Amadeo 供圖]</em></p><p>薑餅裏的撥號器受到了稍微多點的照顧。它變得更暗了，並且谷歌終於解決了原本的直角結合的問題，圓角和圓形已經被拋棄了。現在所有的邊角都是直角了。所有的撥號按鍵被替換成了帶有奇怪下劃線的樣式，像是用邊角料拼湊的。你永遠無法確定是否看到了一個按鈕——我們的大腦得想像出按鈕形狀的剩餘部分。</p><p>圖中的無線網絡對話框可以看作是剩下的系統全局性改動的樣本。所有的對話框標題從灰色變為黑色，對話框、下拉框以及按鈕邊緣都變成了直角，各部分色調都變暗了一點。所有的這些全局變化使得薑餅看起來不像原來那樣活潑，而是更加地成熟。“到處都是黑色”的外觀必然不是最受歡迎的，但它無疑看起來比安卓之前的灰色和米色的配色方案好多了。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/4market.png" alt="新市場，添加了大塊的綠色頁面頂欄。"></p><p><em>新市場，添加了大塊的綠色頁面頂欄。 [Ron Amadeo 供圖]</em></p><p>新版系統帶來了“安卓市場 2.0”，雖然它不是薑餅獨有的。主要的列表設計和原來一致，但谷歌將屏幕上部三分之一覆蓋上了大塊的綠色橫幅，用來展示熱門應用以及導航。這裏主要的設計靈感也許是綠色的安卓吉祥物——它們的顏色完美匹配。在系統設計偏向暗色系的時候，霓虹燈般的綠色橫幅和白色列表讓市場明快得多。</p><p>但是，相同的綠色背景圖片被用在了不同的手機上，這意味着在低分辨率設備上，綠色橫幅看起來更加的大。不少用户抱怨這浪費了屏幕空間，於是隨後的更新使得綠色橫幅跟隨內容向上滾動。在那時，橫屏模式更加糟糕——綠色橫幅會填滿剩下的半個屏幕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/5rest-of-market-and-books.png" alt="市場的一個帶有可摺疊描述的應用詳情頁面，“我的應用”界面，以及Google Books界面截圖。"></p><p><em>市場的一個帶有可摺疊描述的應用詳情頁面，“我的應用”界面，以及 Google Books 界面截圖。 [Ron Amadeo 供圖]</em></p><p>應用詳情頁面經過重新設計有了可摺疊部分。文本描述只截取前幾行展示，向下滑動頁面不用再穿過數千行的描述。簡短的描述後有一個“更多”按鈕可供點擊來顯示完整的描述。這讓用户可以輕鬆地滑動過列表找到像是截圖和“聯繫開發者”部分，這些部分通常在頁面偏下部分。</p><p>安卓主屏的其它部分明智地淡化了綠色機器人元素。市場應用的剩餘部分絕大多數僅僅只是舊版市場加上新的綠色導航元素。舊有的標籤界面升級成了可滑動切換標籤。在薑餅右側截圖中，從右向左滑動將會從“熱門付費”切換至“熱門免費”，這使得導航變得更加方便。</p><p>薑餅帶來了將會成為 Google Play 內容商店第一位成員的應用：Google Books。這個應用是個基礎的電子書閲讀器，會將書籍以簡單的預覽圖平鋪展示。屏幕頂部的“獲取 eBooks”鏈接會打開瀏覽器，然後加載一個你可以在上面購買電子書的移動網站。</p><p>Google Books 以及市場的“我的應用”頁面都是 Action Bar 的早期原型。就像現在的指南中寫的，頁面有一個帶應用圖標的固定置頂欄，應用內頁面的名稱，以及一些控件。這兩個應用的佈局實際上看起來十分現代，和現在的界面相似。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/maps1.png" alt="新版谷歌地圖"></p><p><em>新版谷歌地圖。 [Ron Amadeo 供圖]</em></p><p>谷歌地圖（再重複一次，這時候的谷歌地圖是在安卓市場中的，並且不是這個安卓版本獨佔的）擁有了另一個操作欄原型，這是一個頂部對齊的控件欄。這個早期版本的操作欄擁有許多試驗性功能。功能欄主要被一個搜索框所佔據，但是你永遠無法向其輸入內容。點擊搜索框會打開安卓 1.x 版本以來的舊搜索界面，它帶有完全不同的操作欄設計體驗和活潑的按鈕。2.3 版本的頂欄僅僅只是個大號的搜索按鈕而已。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/maps2-Im-hungry.png" alt="從黑變白的新 business 頁面。"></p><p><em>從黑變白的新 business 頁面。 [Ron Amadeo 供圖]</em></p><p>在應用抽屜裏和“地點”一起到來的“熱門商家”重新設計了界面。不像薑餅的其它部分，它從黑色轉換成了白色。谷歌還給它保留了圓角的舊按鈕。這個新版本的地圖能顯示商家的營業時間，並且提供高級搜索選項，比如正在營業或是通過評分或價格限定搜索範圍。點評被調整到了商家詳情頁面，用户可以更容易地對當前商家有個直觀感受。而且現在還可以從搜索結果中給某個地點加星，保存起來以後使用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/youtube22.png" alt="新 YouTube 設計，神奇的是有點像舊版地圖的商家頁面的設計。"></p><p><em>新 YouTube 設計，神奇的是有點像舊版地圖的商家頁面的設計。 [Ron Amadeo 供圖]</em></p><p>YouTube 應用似乎完全與安卓的其它部分分離開來，就像是設計它的人完全不知道薑餅最終會是什麼樣子一樣。高亮是紅色和灰色方案，而不是綠色和橙色，而且不像扁平黑色風格的薑餅，Youtube 有着氣泡狀的，帶有圓角並且大幅使用漸變效果的按鈕、標籤以及操作欄。儘管如此，新應用還是有一些正確的地方。所有的標籤可以水平滑動切換，而且應用終於提供了豎屏觀看視頻模式。安卓在那個階段似乎工作不是很一致。就像是有人告訴 Youtube 團隊“把它做成黑色的”，然後這就是全部的指導方向一樣。唯一一個與其相似的安卓實體就是舊版谷歌地圖的商家頁面的設計。</p><p>儘管有些奇怪的設計，Youtube 應用有着最接近操作欄的頂欄設計。除了頂部操作欄的應用圖標和一些按鈕，最右側還有個標着“更多”字樣的按鈕，點擊它可以打開因為過多而無法裝進操作欄的選項。在今天，這被稱作“更多操作”按鈕，它是個標準界面控件。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/talkvoice.png" alt="新 Google Talk，支持語音和視頻通話，以及新語音命令界面。"></p><p><em>新 Google Talk，支持語音和視頻通話，以及新語音命令界面。 [Ron Amadeo 供圖]</em></p><p>薑餅的最後一個更新是安卓 2.3.4，它帶來了新版 Google Talk。不像 Nexus One，Nexus S 帶有前置攝像頭——重新設計的 Google Talk 擁有語音和視頻通話功能。好友列表右側的彩色指示不僅指明在線狀態，還顯示了語音和視頻的可用性。一個點表示僅支持文本信息，一個麥克風表示支持文本信息或語音，一個攝像機表示支持文本信息、語音以及視頻。如果可用的話，點擊語音或視頻圖標會立即向好友發起通話。</p><p>薑餅是谷歌仍然提供支持的最老的安卓版本。激活一部薑餅設備並放置一會兒會收到大量更新。薑餅會拉取 Google Play 服務，它會帶來許多新的 API 支持，並且會升級到最新版本的 Play 商店。打開 Play 商店並點擊更新按鈕，幾乎每個獨立谷歌應用都會被替換為更加現代的版本。我們嘗試着保持這篇文章講述的是薑餅發佈時的樣子，但時至今日還停留在薑餅的用户會被認為有點跟不上時代了。</p><p>薑餅如今仍然能夠得到支持，因為有數量可觀的用户仍然在使用這個有點過時的系統。薑餅仍然存在的意義來自於它極低的系統要求，使得它成為了低端廉價設備的最佳選擇。下個版本的安卓對硬件的要求變得更高了。舉個例子，安卓 3.0 蜂巢不是開源的，這意味着它只能在谷歌的協助之下移植到一個設備上。同時它還是隻為平板設計的，這讓薑餅在相當長的一段時間都是最新的手機安卓版本。4.0 冰淇淋三明治是下一個手機版本，但它顯著地提高了安卓系統要求，拋棄了低端市場。谷歌現在希望借 4.4 KitKat（奇巧巧克力）重回廉價手機市場，它的系統要求降回了 512MB 內存。時間的推移同樣有所幫助——如今，就算是廉價的系統級芯片都能滿足安卓 4.0 時代的系統要求。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',35)),a("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...o[0]||(o[0]=[t("Ron Amadeo",-1)])]),_:1}),o[2]||(o[2]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(e,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...o[1]||(o[1]=[t("@RonAmadeo",-1)])]),_:1})]),o[15]||(o[15]=a("hr",null,null,-1)),a("p",null,[o[4]||(o[4]=t("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/15/"},{default:p(()=>[...o[3]||(o[3]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/15/",-1)])]),_:1})]),a("p",null,[o[7]||(o[7]=t("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:p(()=>[...o[5]||(o[5]=[t("alim0x",-1)])]),_:1}),o[8]||(o[8]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...o[6]||(o[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[o[11]||(o[11]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[9]||(o[9]=[t("LCTT",-1)])]),_:1}),o[12]||(o[12]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...o[10]||(o[10]=[t("Linux中國",-1)])]),_:1}),o[13]||(o[13]=t(" 榮譽推出",-1))])])}const x=r(m,[["render",g]]);export{k as __pageData,x as default};
